def clamp(x, a=0.0, b=1.0): return a if x < a else b if x > b else x
def ss(x): x = clamp(x); return x * x * (3 - 2 * x)
def ease(x): x = clamp(x); return x * x * x * (x * (x * 6 - 15) + 10)
def lerp(a, b, k):
