def shot_index(t):
    for i, s in enumerate(SH):
        if s[0] <= t < s[1]: return i
    return len(SH) - 1

# ---------------- train ----------------
LOCO_L = 17.7
WAG_L = 13.0
def train_y(t):
    """y of the locomotive front (train travels -Y)."""
    i = shot_index(t)
    if t < 2.40: return 380.0 - 22.0 * t
    if t < 3.54: return 120.0 - 22.0 * (t - 2.40)
    if t < 4.94: return 900.0 - 24.6 * (t - 3.54)
    if t < 7.76: return 1300.0 - 24.6 * (t - 4.94)
    if t < 15.48: return 1650.0 - 1.5 * (t - 7.76)
    if t < 24.68: return 5000.0
    if t < 31.64: return 620.0 - 6.0 * (t - 24.68)
    if t < 38.50:
        if t < CONTACT: return -0.75 + 8.0 * (CONTACT - t)
        return -0.75 - 7.0 * (1 - math.exp(-(t - CONTACT) / 1.8))
    if t < 40.76: return 5000.0
    if t < 42.98: return 900.0 - 24.6 * (t - 40.76)
    if t < 50.16: return 5000.0
    if t < 52.18: return 1300.0 - 30.0 * (t - 50.16)
    if t < 54.46: return 140.0 - 22.0 * (t - 52.18)
    return 380.0 + 22.0 * (DUR - t)

