def run_path(t, delay, off=(0.0, 0.0)):
    """driver path 24.68-30.94: wrong way (-Y) 24.68-25.1, freeze, rewind 25.8-26.08, spin, run 45 deg (+X,+Y)"""
    start = (-0.9 + off[0], -6.0 + off[1], 0.0)
    td = t - delay
    if td < 24.68: return (start, math.radians(185), "STAND", 0)
    if td < 25.1:  # run away from the train (toward -Y)
        k = (td - 24.68)
        return ((start[0], start[1] - 3.2 * k * (1 if delay == 0 else 0.6), 0), math.radians(0), "RUN", k * 9)
    if td < 25.8:
        k = 0.42
        return ((start[0], start[1] - 3.2 * k * (1 if delay == 0 else 0.6), 0), math.radians(0), "RUNFREEZE", k * 9)
    if td < 26.08:
        k = 0.42 * (1 - (td - 25.8) / 0.28)
        return ((start[0], start[1] - 3.2 * k * (1 if delay == 0 else 0.6), 0), math.radians(0), "RUN", k * 9)
    if td < 26.45:  # spin toward the train at 45 degrees
        k = ramp(td, 26.08, 26.45)
        return (start, lerp(math.radians(0), math.radians(180 + 45), k), "STAND", 0)
    # run at 45 degrees: direction (+X,+Y)/sqrt2 i.e. toward the train (+Y) and away from tracks (+X)
    d = min(td - 26.45, 4.4)
    sp = 3.4
    p = (start[0] + sp * d * 0.7071, start[1] + sp * d * 0.7071, 0.0)
    pose = "RUN" if td - 26.45 < 4.3 else "STAND"
    return (p, math.radians(180 + 45), pose, (td - 26.45) * 9)

# owl: (loc, rotz, head_euler_deg(x,y,z), scale)
OWL_XB = (SIG1[0], SIG1[1], 4.05)
def owl_state(t):
