    if 14.85 <= t < 15.48: head = (0, 0, 0); head = (0, 85 * ramp(t, 14.95, 15.2), 0)
    if 30.94 <= t < 31.64: head = (0, 0, 360 * ease((t - 31.0) / 0.55))
    if t >= 38.9:
