        top = (SIGN[0], SIGN[1], SIGN[2] + 0.22)
        loc = (lerp(OWL_XB[0], top[0], k), lerp(OWL_XB[1], top[1], k), lerp(OWL_XB[2], top[2], k) + 0.6 * math.sin(math.pi * k))
    if t >= 54.46 or t < 0.0: loc = OWL_XB
    if 42.98 <= t < 45.22: sc = 1.0 + 0.18 * pulse(t, 43.0, 43.6)
    return loc, rz, head, sc

# ENS sign glow (0..1) and global dim (1 normal .. 0.25 dimmed)
def sign_glow(t):
    if 38.5 <= t < 48.12: return 0.35 + 0.65 * ramp(t, 42.98, 43.3)
    return 0.0
def world_dim(t):
    if 38.6 <= t < 45.22: return 1.0 - 0.7 * ramp(t, 38.6, 39.1)
    return 1.0

def sparks_on(t):
    if 3.54 <= t < 4.94: return 1.0
    if 40.76 <= t < 42.98: return 1.0 - ramp(t, 42.34, 42.7)
