# balance-scale stage: beam tilt (deg, + = left pan down), loco/car on pans
SCALE_H = 60.0
SCALE_S = SCALE_H / 1.03          # asset is 1.03 tall
PIVOT_Z = 0.71 * SCALE_S
HOOK_X = 0.28 * SCALE_S
PAN_DROP = 0.27 * SCALE_S         # hook to pan bowl
def scale_tilt(t):
    if t < 15.48: return 0.0
    k1 = ease((t - 15.5) / 0.16)
    tilt = 22.0 * k1
    if t > 15.66: tilt += 2.5 * math.sin((t - 15.66) * 22) * math.exp(-(t - 15.66) * 5)
    if t > 16.45: tilt -= 1.5 * math.sin((t - 16.45) * 25) * math.exp(-(t - 16.45) * 6)
    return tilt
def pan_pos(side, t):
    """side -1 = left (train), +1 = right (car); returns bowl centre (world)"""
    th = math.radians(scale_tilt(t))
    x = side * HOOK_X * math.cos(th); z = PIVOT_Z - side * HOOK_X * math.sin(th) * -1.0
    z = PIVOT_Z + (side * HOOK_X) * math.sin(-th) * -1.0
    # left side goes down for positive tilt
    z = PIVOT_Z - (-side) * HOOK_X * math.sin(th)
    return (STAGE[0] + x, STAGE[1], z - PAN_DROP)
def stage_loco(t):
    p = pan_pos(-1, t)
    drop = 0.0 if t >= 15.5 else 25.0 * (1 - ramp(t, 15.2, 15.5))
    return (p[0], p[1], p[2] + 0.8 + drop)
def stage_car(t):
    p = pan_pos(1, t)
    drop = 0.0 if t >= 16.45 else (30.0 * (1 - ramp(t, 16.15, 16.45)) if t >= 15.48 else 60.0)
    hop = 3.0 * pulse(t, 16.45, 16.9)
    return (p[0], p[1], p[2] + 0.6 + drop + hop)

