G_SLOW = 9.81 * 0.28
def debris_state(i, t):
    kind, p0, v, spin = DEBRIS[i]
    if not (31.64 <= t < 38.5) or t < CONTACT + 0.02: return p0, (0, 0, 0), 0.0
    k = t - CONTACT
    if kind == "hubcap":   # lands on the red ghost's head at 35.42, bounces off
        a, b = (CAR0[0] + 0.8, CAR0[1] + 0.6, 0.6), (GHOST[0], GHOST[1], 1.86)
        t1 = 35.42 - CONTACT
        if k <= t1:
            u = k / t1
            p = (lerp(a[0], b[0], u), lerp(a[1], b[1], u), lerp(a[2], b[2], u) + 5.5 * math.sin(math.pi * u))
            return p, (k * 9, k * 5, 0), 1.0
        u = clamp((k - t1) / 0.6)
        p = (b[0] + 1.3 * u, b[1] - 0.9 * u, b[2] * (1 - u) + 0.6 * math.sin(math.pi * u))
        return p, (t1 * 9 + u * 6, t1 * 5, 0), 1.0
    x = p0[0] + v[0] * k; y = p0[1] + v[1] * k
    z = p0[2] + v[2] * k - 0.5 * G_SLOW * k * k
    if z < 0.03:
        # time of landing, then slide/settle
        tl = (v[2] + math.sqrt(v[2] ** 2 + 2 * G_SLOW * p0[2])) / G_SLOW
        sl = clamp((k - tl) / 1.2)
        x = p0[0] + v[0] * (tl + 0.4 * sl); y = p0[1] + v[1] * (tl + 0.4 * sl); z = 0.03
        k = tl + 0.3 * sl
    return (x, y, z), (k * spin, k * spin * 0.7, k * spin * 0.4), 1.0

# ---------------- camera ----------------
def norm(v):
    l = math.sqrt(sum(x * x for x in v)) or 1.0
    return tuple(x / l for x in v)
def cross(a, b): return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])
def dot(a, b): return sum(x * y for x, y in zip(a, b))

