def cam_state(t):
    i = shot_index(t)
    t0, t1, keys, shake = SH[i]
    def kv(k, tt):
        if isinstance(k[1], str):
            p, g = resolve(k[1], tt); return p, g, k[3], k[4]
        return k[1], k[2], k[3], k[4]
    if t <= keys[0][0]: pos, tgt, lens, roll = kv(keys[0], t)
    elif t >= keys[-1][0]: pos, tgt, lens, roll = kv(keys[-1], t)
    else:
        for a, b in zip(keys, keys[1:]):
            if a[0] <= t <= b[0]:
                u = (t - a[0]) / (b[0] - a[0]) if b[0] > a[0] else 1.0
                u = ss(u) if len(keys) > 2 else (0.25 * u + 0.75 * ss(u))
                pa, ga, la, ra = kv(a, t); pb, gb, lb, rb = kv(b, t)
                pos, tgt, lens, roll = lerp(pa, pb, u), lerp(ga, gb, u), lerp(la, lb, u), lerp(ra, rb, u)
                break
    if shake:
        s = shake * (1.0 + 2.0 * pulse(t, 15.48, 15.9))
        pos = (pos[0] + s * math.sin(t * 37.1), pos[1] + s * math.sin(t * 29.3 + 1), pos[2] + s * math.sin(t * 41.7 + 2))
    if 15.48 <= t < 16.2:
        q = 0.35 * math.exp(-(t - 15.5) * 6) * (1 if t > 15.5 else 0)
        pos = (pos[0] + q * math.sin(t * 61), pos[1], pos[2] + q * math.sin(t * 47))
    return pos, tgt, lens, math.radians(roll)

def is_cut_frame(f):
    return shot_index(f / FPS) != shot_index((f + 1) / FPS)

def cam_basis(pos, tgt, roll=0.0):
    f = norm(tuple(tgt[i] - pos[i] for i in range(3)))
    r = norm(cross(f, (0, 0, 1)))
    u = cross(r, f)
    if roll:
        c, s = math.cos(roll), math.sin(roll)
        r, u = tuple(c * r[i] + s * u[i] for i in range(3)), tuple(-s * r[i] + c * u[i] for i in range(3))
    return r, u, f

def project(p, t):
    pos, tgt, lens, roll = cam_state(t)
    r, u, f = cam_basis(pos, tgt, roll)
    d = tuple(p[i] - pos[i] for i in range(3))
    z = dot(d, f)
    if z <= 0.01: return None
    s = lens / (SENSOR / 2)
    x = dot(d, r) / z * s; y = dot(d, u) / z * s
    return (W / 2 + x * H / 2, H / 2 - y * H / 2, z)

